import{_ as l,o as i,c as t,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Crimson/SeaStor OSD Meeting 2020-08-05","description":"","frontmatter":{"title":"Ceph Crimson/SeaStor OSD Meeting 2020-08-05","date":"2020-08-05T00:00:00.000Z","updated":"2020-08-06T00:00:00.000Z","tags":["Ceph","分布式存储","Bluestore","Pull Request","内存数据结构管理"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_Meeting_2020-08-05.md","filePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_Meeting_2020-08-05.md","lastUpdated":1780459816000}'),r={name:"posts/2020/Ceph_Crimson_SeaStor_OSD_Meeting_2020-08-05.md"};function o(s,e,u,n,h,p){return i(),t("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议概要" tabindex="-1">会议概要 <a class="header-anchor" href="#会议概要" aria-label="Permalink to &quot;会议概要&quot;">​</a></h4><p>本次会议主要讨论了Ceph分布式存储系统的发展，重点关注了代码重构、测试结果分析、Pull Request更新、内存数据结构管理等议题。</p><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>代码重构与测试</strong></p><ul><li>创建了一个修复问题的Pull Request，以启用小规模运行测试。</li><li>测试结果显示，部分失败与Bluestore相关，但并非Ceph核心问题。</li><li>计划进一步调查Bluestore中的失败原因。</li></ul></li><li><p><strong>Pull Request更新与审查</strong></p><ul><li>根据评论更新了Pull Request，并请求团队成员审查。</li><li>讨论了在旧节点中启动扩展映射树的问题，决定不在外部映射树中存储。</li><li>代码重构涉及Sam的RBA pin patch，发现了一些问题，等待更新后重新重构。</li></ul></li><li><p><strong>内存数据结构管理</strong></p><ul><li>讨论了在固定KV节点布局中使用cipher_le64的问题，因缺乏常量操作接口，需要提供自己的包装结构。</li><li>讨论了在事务结束后保持对扩展的引用的安全性，建议在同一事务内保持引用，但不要在事务间保持。</li></ul></li><li><p><strong>未来工作计划</strong></p><ul><li>继续开发可中断的叙述未来（interruptible narrative future），并实现一系列错误率版本的未来设施。</li><li>计划实现跟踪设施，以便在树查找中保持节点可用性。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>调查Bluestore中的测试失败原因。</li><li>完成Pull Request的修改和审查。</li><li>在内存数据结构管理中，避免在事务间保持对节点的引用。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>调查Bluestore的测试失败原因。</li><li>继续更新和审查Pull Request。</li><li>开发和实现可中断的叙述未来及相关设施。</li><li>实现跟踪设施，确保在树查找中节点的可用性。</li></ul><h4 id="关键词" tabindex="-1">关键词 <a class="header-anchor" href="#关键词" aria-label="Permalink to &quot;关键词&quot;">​</a></h4><ul><li>Ceph</li><li>Bluestore</li><li>Pull Request (Pull Request)</li><li>extend map tree</li><li>RBA pin patch</li><li>cipher_le64</li><li>interruptible narrative future</li></ul>',11)])])}const c=l(r,[["render",o]]);export{d as __pageData,c as default};
